use bevy::math::{DQuat,DVec3};
use bevy_als::extensions::{control_rig_hierarchy::{RigHierarchy,RigTransform,RigSpace},control_rig_math::RigValue,control_rig_program::RigDefinition};
use serde_json::{Value,json};
mod prior{include!("../471/replay.rs");pub fn source_normalize(v:[f64;4])->[f64;4]{normalize(v)}}
type Q=[f64;4];
fn q(v:&Value)->Q{[v["x"].as_f64().unwrap(),v["y"].as_f64().unwrap(),v["z"].as_f64().unwrap(),v["w"].as_f64().unwrap()]}
fn project(v:Q)->Q{[-v[0],-v[2],-v[1],v[3]]}
fn slerp(a:Q,b:Q,t:f32,mask:u8)->Q{
 let t=t as f64;let mut cos=if mask&1!=0{((a[0]*b[0]+a[1]*b[1])+a[2]*b[2])+a[3]*b[3]}else{DQuat::from_array(project(a)).dot(DQuat::from_array(project(b)))};let sign=if cos>=0.{1.}else{-1.};cos*=sign;let mut x=1.-t;let mut y=t*sign;if cos<0.9999{let omega=cos.acos();let reciprocal=1./omega.sin();if mask&1!=0{x=(x*omega).sin()*reciprocal;y=(y*omega).sin()*reciprocal;}else{x=(x*omega).sin()/omega.sin();y=(y*omega).sin()/omega.sin();}}let v=std::array::from_fn(|i|x*a[i]+y*b[i]);if mask&2!=0{prior::source_normalize(v)}else{project(bevy_als::extensions::control_rig_hierarchy::rig_normalize(DQuat::from_array(project(v))).to_array())}
}
fn source(before:Q,value:Q,weight:f32)->(Q,Q,bool){if weight<1e-8{return(before,before,true);}let weighted=if weight<1.-1e-8_f32{slerp(before,value,weight,3)}else{value};let skip=bevy_als::extensions::control_rig_hierarchy::rig_quat_near(DQuat::from_array(before),DQuat::from_array(weighted),1e-4_f32 as f64);(if skip{before}else{weighted},weighted,skip)}
fn transform(v:&Value)->RigTransform{let t=&v["translation"];let z=&v["scale"];RigTransform{rotation:DQuat::from_array(project(q(&v["rotation"]))),translation:DVec3::new(t["x"].as_f64().unwrap()*0.01,t["z"].as_f64().unwrap()*0.01,t["y"].as_f64().unwrap()*0.01),scale:DVec3::new(z["x"].as_f64().unwrap(),z["z"].as_f64().unwrap(),z["y"].as_f64().unwrap())}}
fn public(def:&RigDefinition,name:&str,before:RigTransform,value:Q,weight:f32)->RigTransform{let mut h=RigHierarchy::new(def.bones.clone(),0.0).unwrap();let i=h.index(name).unwrap();h.set_transform(i,RigSpace::Global,false,before,true).unwrap();assert_eq!(h.transform(i,RigSpace::Global,false).unwrap(),before);let initial=h.transform(i,RigSpace::Global,true).unwrap();let mut args=vec![RigValue::List(vec![RigValue::Name("Bone".into()),RigValue::Name(name.into())]),RigValue::Name("GlobalSpace".into()),RigValue::Bool(false),RigValue::Quaternion(DQuat::from_array(project(value))),RigValue::F32(weight),RigValue::Bool(true),RigValue::List(vec![])];h.call_transform_unit("FRigUnit_SetRotation::Execute",&mut args,false).unwrap();assert_eq!(h.transform(i,RigSpace::Global,true).unwrap(),initial);h.transform(i,RigSpace::Global,false).unwrap()}
fn main(){let root=std::path::Path::new("docs/audit/bf144/473");let label=std::env::args().nth(1).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(root.join("inputs.json")).unwrap()).unwrap();let def:RigDefinition=serde_json::from_value(input["definition"].clone()).unwrap();let mut rows=Vec::new();let mut exact=0;for r in input["rows"].as_array().unwrap(){let before=q(&r["before"]["rotation"]);let value=std::array::from_fn(|i|r["value"][i].as_f64().unwrap());let weight=r["weight"].as_f64().unwrap()as f32;let(after,weighted,skip)=source(before,value,weight);let native=q(&r["expected_after"]["rotation"]);if after==native{exact+=1;}let target=public(&def,r["foot"].as_str().unwrap(),transform(&r["before"]),value,weight);let runtime_source=transform(&r["expected_after"]);assert_eq!(target.translation,runtime_source.translation);assert_eq!(target.scale,runtime_source.scale);rows.push(json!({"dataset":r["dataset"],"case":r["case"],"query":r["query"],"pc":r["pc"],"weight":weight,"before":before,"value":value,"weighted":weighted,"source_after":after,"native_after":native,"source_skip":skip,"source_exact":after==native,"public_after":project(target.rotation.to_array()),"public_exact":target==runtime_source}));}
 let actual:Value=serde_json::from_slice(&std::fs::read(root.join("actual.json")).unwrap()).unwrap();let mut matrix=Vec::new();let mut public_exact=0;let mut source_endpoint_exact=0;for r in actual["rows"].as_array().unwrap(){let current_before:RigTransform=serde_json::from_value(r["before"].clone()).unwrap();let current_value=project(std::array::from_fn(|i|r["value"][i].as_f64().unwrap()));let observed:RigTransform=serde_json::from_value(r["observed"].clone()).unwrap();let native_before=transform(&r["source"]["before"]);let native_after=transform(&r["source"]["expected_after"]);let native_value=std::array::from_fn(|i|r["source"]["value"][i].as_f64().unwrap());let weight=r["weight"].as_f64().unwrap()as f32;for mask in 0..4{for source_math in[false,true]{let before=if mask&1!=0{native_before}else{current_before};let value=if mask&2!=0{native_value}else{current_value};let output=if source_math{let mut out=before;out.rotation=DQuat::from_array(project(source(project(before.rotation.to_array()),value,weight).0));out}else{public(&def,r["foot"].as_str().unwrap(),before,value,weight)};if mask==0&&!source_math{assert_eq!(output,observed,"Independent writer matches actual full VM cached global");public_exact+=1;}if mask==3&&source_math{assert_eq!(output,native_after);source_endpoint_exact+=1;}matrix.push(json!({"mode":r["mode"],"query":r["query"],"pc":r["pc"],"data_mask":mask,"source_math":source_math,"result":output,"native":native_after,"exact":output==native_after}));}}}
 let mut factors=Vec::new();for r in input["rows"].as_array().unwrap(){let before=q(&r["before"]["rotation"]);let value=std::array::from_fn(|i|r["value"][i].as_f64().unwrap());let weight=r["weight"].as_f64().unwrap()as f32;for mask in 0..4{let weighted=if weight<1e-8{before}else if weight<1.-1e-8_f32{slerp(before,value,weight,mask)}else{value};let output=if bevy_als::extensions::control_rig_hierarchy::rig_quat_near(DQuat::from_array(before),DQuat::from_array(weighted),1e-4_f32 as f64){before}else{weighted};if mask==0{assert_eq!(project(public(&def,r["foot"].as_str().unwrap(),transform(&r["before"]),value,weight).rotation.to_array()),output,"Current Slerp factor model matches common public unit");}factors.push(json!({"dataset":r["dataset"],"case":r["case"],"query":r["query"],"pc":r["pc"],"weight":weight,"mask":mask,"weighted":weighted,"result":output,"native":q(&r["expected_after"]["rotation"]),"exact":output==q(&r["expected_after"]["rotation"])}));}}
 assert_eq!(public_exact,1272);assert_eq!(source_endpoint_exact,1272);let report=json!({"gate":"SOURCE_SETROTATION_GLOBAL_WRITER_AND_COMMON_PUBLIC_DATA","source_exact":exact,"rows":rows,"actual_public_exact":public_exact,"actual_source_endpoint_exact":source_endpoint_exact,"matrix":matrix,"factors":factors});std::fs::write(root.join(format!("setter-{label}.json")),serde_json::to_vec(&report).unwrap()).unwrap();assert_eq!(exact,696,"Complete source weighted and equality global writer");println!("Verified696 exact source zero/partial/full global rotation writes and common public calls");}
